import React, { useEffect, useState } from "react";
import { ToastContainer, toast } from "react-toastify";
import { Link, useNavigate, useParams } from "react-router-dom";
import { BiLogOutCircle } from "react-icons/bi";
import { useFormik } from "formik";
import * as yup from "yup";
import { makeApiRequest } from "../../axiosService/ApiCall";
import { decryptData } from "../../Auth/SecurityCrypto";
import axios from "axios";

function EditSubAdmin() {
  const { id } = useParams();
  const [adminType, setAdminType] = useState("");
  const [rolePermissions, setRolePermissions] = useState({
    permissions: {
      pairList: { View: 0, Edit: 0 },
      userRequest: { View: 0, Edit: 0 },
      transactionList: { View: 0 },
      orderHistory: { View: 0 },
      tradeHistory: { View: 0 },
      cryptoFiat: { View: 0 },
      swapHistory: { View: 0 },
      notification: { View: 0, Edit: 0 },
      siteSetting: { View: 0, Edit: 0 },
      cms: { View: 0, Edit: 0 },
      subAdmin: { View: 0, Edit: 0 },
      supportTicket: { View: 0, Edit: 0} 

    },
  });

  const navigate = useNavigate();

  // ✅ Checkbox handle
  const handlePermissionChange = (module, action, checked) => {
    setRolePermissions((prev) => {
      let currentModule = prev.permissions[module];

      let updatedModule = {
        ...currentModule,
        ...(currentModule.hasOwnProperty(action) && {
          [action]: checked ? 1 : 0,
        }),
      };

      // 👉 Rule 1: If Edit is enabled, View must also be enabled
      if (action === "Edit" && checked) {
        updatedModule.View = 1;
      }

      // 👉 Rule 2: If View is disabled, Edit must also be disabled
      if (
        action === "View" &&
        !checked &&
        currentModule.hasOwnProperty("Edit")
      ) {
        updatedModule.Edit = 0;
      }

      return {
        permissions: {
          ...prev.permissions,
          [module]: updatedModule,
        },
      };
    });
  };

  // ✅ Formik setup
  const formik = useFormik({
    initialValues: {
      email: "",
      adminPermissions: {},
    },
    validationSchema: yup.object().shape({
      email: yup.string().email("Invalid email").required("Enter Email"),
    }),
    onSubmit: async (values) => {
      const hasAnyPermission = Object.values(rolePermissions.permissions).some(
        (module) =>
          (module.View && module.View === 1) ||
          (module.Edit && module.Edit === 1)
      );

      if (!hasAnyPermission) {
        toast.error("Please edit at least one permission!");
        return;
      }
      const isUnchanged =
        JSON.stringify(rolePermissions.permissions) ===
        JSON.stringify(formik.initialValues.adminPermissions);
      // console.log(" old permissions:", formik.initialValues.adminPermissions);
      // console.log("new permissions:", rolePermissions.permissions);
      // console.log("any change:", isUnchanged);

      if (isUnchanged) {
        toast.info("No changes Made");
        return;
      }


      try {
        const address = await axios.get("https://api.ipify.org/?format=json");

        const lastloginIpAddress = address.data.ip;

        const updatedValues = {
          adminPermissions: rolePermissions.permissions,
          ip: lastloginIpAddress
        };

        const params = {
          url: `edit-subAdmin/${id}`,
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
          data: updatedValues,
        };

        const editSubAdminEncryptres = await makeApiRequest(params);
        // console.log("editSubAdminEncryptres", editSubAdminEncryptres);
        const decrypteditSubAdminEncryptres = decryptData(
          editSubAdminEncryptres.data
        );
        // console.log("decrypteditSubAdminEncryptres",decrypteditSubAdminEncryptres);

        if (decrypteditSubAdminEncryptres.status == true) {
          toast.success(decrypteditSubAdminEncryptres.message);
          setTimeout(() => {
            navigate("/dashboard/subadmin");
            //window.location.href = "/dashboard/subadmin";
          }, 2000);
        } else if (decrypteditSubAdminEncryptres.status == false) {
          toast.error(
            decrypteditSubAdminEncryptres.message || "Something went wrong!"
          );
        } else {
          toast.error("Something went wrong!");
        }
      } catch (error) {
        console.error("Error:", error);
        toast.error("Error in form submission");
      }
    },
  });

  // ✅ Fetch old data
  useEffect(() => {
    const fetchSubAdmin = async () => {
      try {
        const params = {
          url: `getOneUserData/${id}`,
          method: "GET",
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        };

        const userDataresult = await makeApiRequest(params);
        // console.log("resultedit>>>", userDataresult);

        if (userDataresult.status) {
          formik.setValues({
            email: userDataresult.data.email,
          });

          formik.initialValues.adminPermissions =
            userDataresult.data.adminPermissions;
          setRolePermissions({
            permissions: userDataresult.data.adminPermissions,
          });
          setAdminType(userDataresult.data.admin_type);
        } else {
          toast.error("User not found!");
        }
      } catch (error) {
        console.error(error);
        toast.error("Failed to fetch user data");
      }
    };

    fetchSubAdmin();
  }, [id]);

  return (
    <div className="container mt-4">
      <ToastContainer />
      <div className="custom-saled-order">
        <div className="row">
          <div className="col-lg-12">
            <div className="py-3 justify-content-center d-flex justify-content-between">
              <h3 className="component-user text-center ms-lg-0">
                <Link to="/dashboard/subadmin">
                  <BiLogOutCircle />
                </Link>{" "}
                Edit Sub Admin
              </h3>
            </div>

            {/* Form */}
            <form onSubmit={formik.handleSubmit}>
              {/* Email (read-only) */}
              <div className="mb-3">
                <label>Email</label>
                <input
                  type="email"
                  name="email"
                  value={formik.values.email}
                  readOnly
                  className="form-control"
                />
              </div>
              <div className="mb-3 mt-4">
                <h5 className="mb-4">Permissions</h5>
                {Object.keys(rolePermissions.permissions).map((module, i) => {
                  if (
                    adminType !== "SuperAdmin" &&
                    (module === "adminTransfer" || module === "adminSetting")
                  ) {
                    return null; // skip
                  }

                  return (
                    <div key={i} className="mb-2 select-box mt-2">
                      <div className="row">
                        <div className="col-lg-3">
                          <label className="me-3 form-label">{module}</label>
                        </div>

                        {/* View */}
                        {rolePermissions.permissions[module].hasOwnProperty(
                          "View"
                        ) && (
                            <div className="col-lg-2">
                              <div className="form-check form-check-inline">
                                <input
                                  type="checkbox"
                                  className="form-check-input"
                                  checked={
                                    rolePermissions.permissions[module].View === 1
                                  }
                                  onChange={(e) =>
                                    handlePermissionChange(
                                      module,
                                      "View",
                                      e.target.checked
                                    )
                                  }
                                />
                                <label className="form-check-label">View</label>
                              </div>
                            </div>
                          )}

                        {/* Edit Checkbox */}
                        {rolePermissions.permissions[module].hasOwnProperty(
                          "Edit"
                        ) && (
                            <div className="col-lg-2">
                              <div className="form-check form-check-inline">
                                <input
                                  type="checkbox"
                                  className="form-check-input"
                                  checked={
                                    rolePermissions.permissions[module].Edit === 1
                                  }
                                  onChange={(e) =>
                                    handlePermissionChange(
                                      module,
                                      "Edit",
                                      e.target.checked
                                    )
                                  }
                                />
                                <label className="form-check-label">Edit</label>
                              </div>
                            </div>
                          )}
                      </div>
                    </div>
                  );
                })}
              </div>

              <button
                type="submit"
                className="custom-nav-button-1 active mb-3 pr-3"
              >
                Update
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

export default EditSubAdmin;
